-- Personalización de "Haz tu menú": el cliente pidió que cada menú
-- tenga las mismas opciones que su versión suelta (elegir carne, salsas,
-- extras...) en vez de ser un único producto genérico sin personalizar, y
-- que TODOS los menús dejen elegir bebida.
--
-- Usa un campo nuevo, "siempreEnTexto" (paso-level, junto a "titulo"/
-- "opciones"): para pasos de "elige uno obligatorio" sin coste en el
-- precio base (carne, tipo de patatas, tipo de hamburguesa, sabor de
-- pizza, bebida), la opción elegida SIEMPRE sale en el ticket de cocina,
-- incluso si es la de por defecto — igual que ya hacía "esSelectorTamano"
-- para el tamaño de pizza, pero sin tocar el precio (sigue sumando
-- precioExtra normal, no sustituye el precio base). IMPORTANTE: este
-- campo requiere el código desplegado en el commit que añade
-- "siempreEnTexto" a orders/index.js y Personalizar.jsx — no ejecutar
-- este script hasta confirmar que ese código ya está en producción (ver
-- SKILL.md, "Reorganización de carta").
-- Seguro de re-ejecutar.

update menu_productos set modificadores = '[{"id":"carne","titulo":"Elige la carne","tipo":"unica","maxSeleccion":1,"siempreEnTexto":true,"opciones":[{"id":"ternera","nombre":"Ternera","precioExtra":0,"porDefecto":true},{"id":"pollo","nombre":"Pollo","precioExtra":0,"porDefecto":false},{"id":"mixto","nombre":"Mixto","precioExtra":0,"porDefecto":false}]},{"id":"quitar","titulo":"Quitar ingredientes","tipo":"multiple","resumenQuitarMuchos":{"umbral":3,"siTodoVacio":"Solo carne"},"precioSiTodoQuitado":8.5,"disparadoresPrecioAlternativo":["sin-lechuga","sin-repollo-zanahoria"],"opciones":[{"id":"sin-tomate","nombre":"Sin tomate","ingrediente":"tomate","precioExtra":0,"porDefecto":false},{"id":"sin-cebolla","nombre":"Sin cebolla","ingrediente":"cebolla","precioExtra":0,"porDefecto":false},{"id":"sin-repollo-zanahoria","nombre":"Sin repollo y zanahoria","ingrediente":"repollo y zanahoria","precioExtra":0,"porDefecto":false},{"id":"sin-lechuga","nombre":"Sin lechuga","ingrediente":"lechuga","precioExtra":0,"porDefecto":false}]},{"id":"tipo-patatas","titulo":"Tus patatas","tipo":"unica","maxSeleccion":1,"siempreEnTexto":true,"opciones":[{"id":"fritas","nombre":"Patatas fritas","precioExtra":0,"porDefecto":true},{"id":"deluxe","nombre":"Patatas deluxe","precioExtra":1.5,"porDefecto":false}]},{"id":"salsas","titulo":"Salsas","tipo":"multiple","textoSiVacio":"Sin salsa","opciones":[{"id":"salsa-blanca","nombre":"Salsa de yogurt (Blanca)","ingrediente":"salsa blanca","precioExtra":0,"porDefecto":true},{"id":"salsa-roja","nombre":"Salsa de tomate (Roja)","ingrediente":"salsa roja","precioExtra":0,"porDefecto":true},{"id":"salsa-picante","nombre":"Salsa picante","ingrediente":"salsa picante","precioExtra":0,"porDefecto":false}]},{"id":"salsas-aparte","titulo":"Tarrinas de salsa aparte","tipo":"multiple","opciones":[{"id":"salsa-blanca","nombre":"Tarrina Salsa de yogurt (Blanca)","precioExtra":1,"porDefecto":false},{"id":"salsa-roja","nombre":"Tarrina Salsa de tomate (Roja)","precioExtra":1,"porDefecto":false},{"id":"salsa-picante","nombre":"Tarrina Salsa picante","precioExtra":1,"porDefecto":false}]},{"id":"extras","titulo":"Extras","tipo":"multiple","opciones":[{"id":"extra-salsa","nombre":"Extra salsa","precioExtra":1,"porDefecto":false},{"id":"extra-queso","nombre":"Extra queso","precioExtra":1,"porDefecto":false}]},{"id":"bebida","titulo":"Elige tu bebida","tipo":"unica","maxSeleccion":1,"siempreEnTexto":true,"opciones":[{"id":"coca-cola","nombre":"Coca-Cola","precioExtra":0,"porDefecto":true},{"id":"coca-cola-cero","nombre":"Coca-Cola 0","precioExtra":0,"porDefecto":false},{"id":"aquarius-limon","nombre":"Aquarius limón","precioExtra":0,"porDefecto":false},{"id":"fuze-tea","nombre":"Fuze Tea","precioExtra":0,"porDefecto":false},{"id":"zumo-tropical","nombre":"Zumo tropical","precioExtra":0,"porDefecto":false},{"id":"fanta-naranja","nombre":"Fanta naranja","precioExtra":0,"porDefecto":false},{"id":"monster","nombre":"Monster","precioExtra":0,"porDefecto":false},{"id":"agua","nombre":"Agua","precioExtra":0,"porDefecto":false}]}]'::jsonb where id = 'menu-doner-kebab';
